  const organizationDisplayName = `harbor-saaskit-org-${runId}`;

  const scalekit = new ScalekitClient(
    requireEnv('SCALEKIT_ENV_URL'),
    requireEnv('SCALEKIT_CLIENT_ID'),
    requireEnv('SCALEKIT_CLIENT_SECRET'),
  );

  const response = await scalekit.organization.createOrganization(organizationDisplayName);
  const organizationId = response.organization?.id;

  if (!organizationId) {
    throw new Error('Scalekit did not return an organization ID.');
